package email

import (
	"fmt"
	"html"
	"net/url"
	"time"
)

// magicLinkBodies renders the plain-text and HTML bodies every real sender
// uses. Anyone can type any address into /begin, so the message says
// plainly that someone asked for it, where (the issuer's host, taken from
// the link) and when, and that ignoring it is safe: nothing is verified
// unless the link is opened. It never includes the requester's IP.
//
// magicLinkURL is generated by the server, never user-supplied; it is still
// escaped.
func magicLinkBodies(magicLinkURL string, requestedAt time.Time) (plain, htmlBody string) {
	host := "the Personhood issuer"
	if u, err := url.Parse(magicLinkURL); err == nil && u.Host != "" {
		host = u.Host
	}
	when := requestedAt.UTC().Format("2006-01-02 15:04 UTC")

	plain = fmt.Sprintf(
		"Someone asked %s to confirm this email address for Personhood enrollment on %s.\r\n\r\n"+
			"If that was you, tap the link to confirm:\r\n\r\n%s\r\n\r\n"+
			"This link expires in 15 minutes. If it wasn't you, ignore this email: "+
			"nothing is verified unless the link is opened.",
		host, when, magicLinkURL,
	)
	link := html.EscapeString(magicLinkURL)
	htmlBody = fmt.Sprintf(
		`<!doctype html><html><body style="font-family:system-ui,sans-serif;line-height:1.5;color:#0f1115">`+
			`<p>Someone asked %s to confirm this email address for Personhood enrollment on %s.</p>`+
			`<p>If that was you, tap the button below.</p>`+
			`<p><a href="%s" style="display:inline-block;padding:10px 16px;border-radius:8px;background:#0f1115;color:#fff;text-decoration:none">Confirm email</a></p>`+
			`<p style="color:#6b7280;font-size:14px">Or open this link directly: <a href="%s">%s</a></p>`+
			`<p style="color:#6b7280;font-size:14px">This link expires in 15 minutes. If it wasn't you, ignore this email: nothing is verified unless the link is opened.</p>`+
			`</body></html>`,
		html.EscapeString(host), when, link, link, link,
	)
	return plain, htmlBody
}
